$results=[];
function check($name,$fn){global $results;try{$fn();$results[]=['name'=>$name,'ok'=>true];}catch(Throwable $e){$results[]=['name'=>$name,'ok'=>false,'error'=>$e->getMessage()];}}
function same($a,$b){if($a!==$b)throw new RuntimeException('Expected '.json_encode($b).', got '.json_encode($a));}
function throws($fn){try{$fn();}catch(Throwable $e){return;}throw new RuntimeException('Expected rejection.');}
