check('Designer preview and library enforce ownership and capabilities',function()use($model){$author=get_user_by('login','test_author');wp_set_current_user($author->ID);$preview=new WP_REST_Request('POST','/gmpp/v1/designs/preview');$preview->set_header('Content-Type','application/json');$preview->set_body(wp_json_encode(['passport_id'=>$model['id'],'design'=>Giuliomax\Passport\Designs::presets()[0]]));same(rest_do_request($preview)->get_status(),403);$save=new WP_REST_Request('POST','/gmpp/v1/designs');$save->set_header('Content-Type','application/json');$save->set_body(wp_json_encode(['version'=>Giuliomax\Passport\Designs::library()['version'],'design'=>Giuliomax\Passport\Designs::presets()[0]]));same(rest_do_request($save)->get_status(),403);wp_set_current_user(0);same(rest_do_request(new WP_REST_Request('GET','/gmpp/v1/designs'))->get_status(),401);wp_set_current_user(1);$preview=new WP_REST_Request('POST','/gmpp/v1/designs/preview');$preview->set_body_params(['design'=>Giuliomax\Passport\Designs::presets()[0]]);$response=rest_do_request($preview);same($response->get_status(),200);same(str_contains($response->get_data()['html'],'gmpp-design'),true);same($response->get_data()['sample'],true);});
check('A variant replaces a visual design as one unit and can restore inheritance',function(){$presets=Giuliomax\Passport\Designs::presets();$parent=Passport::create(['data'=>['name'=>'Design parent','sku'=>'DESIGN-PARENT','design'=>$presets[0]]]);$child=Passport::create(['kind'=>'variant','parent_id'=>$parent['id'],'data'=>['name'=>'Design child','sku'=>'DESIGN-CHILD','design'=>$presets[4]]]);same($child['effective']['design'],$presets[4]);$child=Passport::save($child['id'],['reset'=>['design']],$child['lock_version']);same($child['effective']['design'],$presets[0]);$child=Passport::save($child['id'],['design'=>null],$child['lock_version']);same($child['effective']['design'],null);});
check('English defaults and standard Italian catalogues preserve user content',function()use($model){same(Giuliomax\Passport\I18n::with_language('en',fn()=>__('Save template','giuliomax-product-passport')),'Save template');same(Giuliomax\Passport\I18n::with_language('it',fn()=>__('Save template','giuliomax-product-passport')),'Salva template');same(__('Save template','giuliomax-product-passport'),'Save template');$s=Passport::published($model['uuid']);$s['data']['design']=Giuliomax\Passport\Designs::presets()[0];$before=$s['data']['name'];same(str_contains(Giuliomax\Passport\Designs::render($s,'en'),'Manuals and documents'),true);same(str_contains(Giuliomax\Passport\Designs::render($s,'it'),'Manuali e documenti'),true);same($s['data']['name'],$before);});
